#!/bin/bash
set -euo pipefail

ROOT="$(pwd)"
if [ ! -f "$ROOT/package.json" ] || [ ! -d "$ROOT/src" ]; then
  echo "ERROR: Run this script from the PaperRaj project root."
  exit 1
fi

BACKUP="$ROOT/.paperraj-mobile-redesign-backup-$(date +%Y%m%d-%H%M%S)"
mkdir -p "$BACKUP"

backup_file() {
  local f="$1"
  if [ -f "$ROOT/$f" ]; then
    mkdir -p "$BACKUP/$(dirname "$f")"
    cp "$ROOT/$f" "$BACKUP/$f"
  fi
}

for f in \
  src/components/Logo.tsx \
  src/components/SiteHeader.tsx \
  src/components/SiteFooter.tsx \
  src/components/StatsStrip.tsx \
  src/components/Library.tsx \
  src/components/PaperViewer.tsx \
  src/app/page.tsx \
  src/app/globals.css
 do backup_file "$f"; done

# Embed the supplied PaperRaj logo so this remains a ONE-FILE installer.
LOGO_B64=''
mkdir -p "$ROOT/public"
printf '%s' "$LOGO_B64" | base64 -d > "$ROOT/public/paperraj-logo.png"
echo "✓ public/paperraj-logo.png: supplied logo installed"

python3 - "$ROOT" <<'PY'
import pathlib, re, sys

root = pathlib.Path(sys.argv[1])

def write(rel, text):
    (root / rel).write_text(text, encoding="utf-8")
    print(f"✓ {rel}: redesigned")

def patch(rel, old, new, label):
    p = root / rel
    s = p.read_text(encoding="utf-8")
    if new in s:
        print(f"✓ {rel}: {label} (already applied)")
        return
    if old not in s:
        raise RuntimeError(f"expected source not found in {rel}: {label}")
    p.write_text(s.replace(old, new, 1), encoding="utf-8")
    print(f"✓ {rel}: {label}")

# Logo: keep the existing component API so every existing consumer continues to work.
write("src/components/Logo.tsx", '''export function Logo({ size = 44, className = "" }: { size?: number; className?: string }) {
  const width = Math.round(size * 1.5);
  return (
    <img
      src="/paperraj-logo.png"
      width={width}
      height={size}
      alt="PaperRaj"
      className={`block h-auto w-auto object-contain ${className}`}
      draggable={false}
    />
  );
}

// Kept for compatibility with any existing imports. The supplied logo already contains the wordmark.
export function LogoWordmark({ compact = false }: { compact?: boolean }) {
  return (
    <span className={`font-display font-semibold text-ink ${compact ? "text-xl" : "text-2xl"}`}>
      Paper<span className="text-wood-2">Raj</span>
    </span>
  );
}
''')

# Header: use the supplied combined logo instead of the old seal + separate wordmark.
header = root / "src/components/SiteHeader.tsx"
s = header.read_text(encoding="utf-8")
s = s.replace('import { Logo, LogoWordmark } from "@/components/Logo";', 'import { Logo } from "@/components/Logo";')
s = re.sub(
    r'<Link\n\s+href="/"\n\s+className="flex shrink-0 items-center gap-3 rounded-sm"\n\s+aria-label="PaperRaj home"\n\s+>.*?</Link>',
    '''<Link
            href="/"
            className="flex shrink-0 items-center rounded-sm"
            aria-label="PaperRaj home"
          >
            <Logo
              size={64}
              className="h-14 w-auto sm:h-16"
            />
          </Link>''',
    s,
    count=1,
    flags=re.S,
)
s = s.replace("<LogoWordmark />", "<Logo />")
s = s.replace('className="flex items-center gap-3 py-3 sm:gap-5 sm:py-4"', 'className="flex items-center gap-2 py-2.5 sm:gap-5 sm:py-3.5"')
s = s.replace('className="ml-auto flex items-center gap-2"', 'className="ml-auto flex items-center gap-1.5 sm:gap-2"')
s = s.replace('className="btn btn-primary btn-sm sm:!min-h-[44px] sm:!px-4"', 'className="btn btn-primary btn-sm !min-h-[40px] !px-3 sm:!min-h-[44px] sm:!px-4"')
s = s.replace('className="btn btn-ghost !px-3"', 'className="btn btn-ghost !min-h-[40px] !px-2.5 sm:!min-h-[44px] sm:!px-3"')
header.write_text(s, encoding="utf-8")
print("✓ src/components/SiteHeader.tsx: compact logo/header hierarchy")

# Homepage: make the real purpose the first thing users see; remove the oversized marketing copy and home About block.
write("src/app/page.tsx", '''import Link from "next/link";
import type { Metadata } from "next";
import { Library } from "@/components/Library";
import { StatsStrip } from "@/components/StatsStrip";
import { SITE } from "@/lib/site";

export const metadata: Metadata = {
  title: "PaperRaj — School Question Papers",
  description: SITE.description,
  alternates: { canonical: "/" },
};

export default function HomePage() {
  return (
    <div className="grid gap-6 sm:gap-8">
      <section className="paper paper-lined overflow-hidden">
        <div className="relative p-4 sm:p-7 lg:p-8">
          <div className="max-w-3xl">
            <p className="smallcaps text-[0.68rem] font-bold text-wood-2 sm:text-[0.74rem]">
              School question paper archive
            </p>
            <h1 className="mt-2 max-w-2xl font-display text-[2rem] font-semibold leading-[1.02] text-ink sm:text-[2.8rem] lg:text-[3.15rem]">
              Find the paper you need.
            </h1>
            <p className="mt-3 max-w-2xl font-serif-papr text-[1rem] leading-relaxed text-ink-2 sm:text-[1.08rem]">
              Browse, view and download school examination papers — or share one with the next student.
            </p>

            <div className="mt-5 grid gap-2 sm:flex sm:flex-wrap">
              <Link href="#library" className="btn btn-primary sm:min-w-[150px]">
                📚 Browse papers
              </Link>
              <Link href="/upload" className="btn sm:min-w-[150px]">
                📤 Upload a paper
              </Link>
              <Link href="/year-papers" className="btn btn-ghost sm:min-w-[120px]">
                Year papers
              </Link>
            </div>

            <p className="mt-3 text-[0.74rem] text-ink-3 sm:text-[0.8rem]">
              No account needed to browse or download · PDF, JPG, PNG and WebP · Up to 50 MB
            </p>
          </div>
        </div>
      </section>

      <section id="library" aria-label="Paper library" className="scroll-mt-20">
        <Library syncUrl />
      </section>

      <section className="paper paper-lined p-3.5 sm:p-5">
        <div className="flex items-center justify-between gap-3">
          <div>
            <p className="smallcaps text-[0.68rem] font-bold text-ink-3">Archive at a glance</p>
            <p className="mt-0.5 font-serif-papr text-sm text-ink-2">Growing with every contribution.</p>
          </div>
          <Link href="/statistics" className="link-ink shrink-0 text-sm">Statistics</Link>
        </div>
        <div className="mt-3">
          <StatsStrip compact />
        </div>
      </section>
    </div>
  );
}
''')

# Stats: compact cards on phones, still rich on larger screens.
stats = root / "src/components/StatsStrip.tsx"
s = stats.read_text(encoding="utf-8")
s = s.replace('className="grid grid-cols-2 gap-2 sm:grid-cols-4"', 'className="grid grid-cols-2 gap-1.5 sm:grid-cols-4 sm:gap-2"')
s = s.replace('className="shelf px-3 py-3 text-center"', 'className="shelf px-2 py-2.5 text-center sm:px-3 sm:py-3"')
s = s.replace('className="font-display text-[1.5rem] font-semibold leading-none text-ink"', 'className="font-display text-[1.2rem] font-semibold leading-none text-ink sm:text-[1.5rem]"')
s = s.replace('className="smallcaps mt-1.5 text-[0.68rem] font-bold text-ink-3"', 'className="smallcaps mt-1 text-[0.58rem] font-bold leading-tight text-ink-3 sm:mt-1.5 sm:text-[0.68rem]"')
stats.write_text(s, encoding="utf-8")
print("✓ src/components/StatsStrip.tsx: compact stats")

# Footer: desktop remains rich; mobile becomes a compact expandable navigation.
write("src/components/SiteFooter.tsx", '''import Link from "next/link";
import { Logo } from "@/components/Logo";
import { SITE } from "@/lib/site";

const LINK_GROUPS: { title: string; links: { href: string; label: string; external?: boolean }[] }[] = [
  {
    title: "The Library",
    links: [
      { href: "/papers", label: "All Papers" },
      { href: "/year-papers", label: "Year Papers" },
      { href: "/specimen-papers", label: "Specimen Papers" },
      { href: "/upload", label: "Upload" },
      { href: "/my-uploads", label: "My Uploads" },
    ],
  },
  {
    title: "Catalogues",
    links: [
      { href: "/subjects", label: "Subjects" },
      { href: "/classes", label: "Classes" },
      { href: "/boards", label: "Boards" },
      { href: "/teachers", label: "Teachers" },
      { href: "/statistics", label: "Statistics" },
    ],
  },
  {
    title: "PaperRaj",
    links: [
      { href: "/about", label: "About" },
      { href: "/contact", label: "Contact" },
      { href: "/privacy", label: "Privacy" },
      { href: "/terms", label: "Terms" },
      { href: SITE.youtubeUrl, label: "YouTube", external: true },
      { href: `mailto:${SITE.ownerEmail}`, label: "Gmail", external: true },
    ],
  },
];

function FooterLinks({ group }: { group: (typeof LINK_GROUPS)[number] }) {
  return (
    <nav aria-label={group.title}>
      <h2 className="smallcaps mb-3 text-[0.76rem] font-bold text-ink-3">{group.title}</h2>
      <ul className="grid gap-2">
        {group.links.map((link) => (
          <li key={link.href}>
            {link.external ? (
              <a href={link.href} target="_blank" rel="noreferrer noopener" className="text-[0.9rem] text-ink-2 hover:text-ink">
                {link.label}
              </a>
            ) : (
              <Link href={link.href} className="text-[0.9rem] text-ink-2 hover:text-ink">
                {link.label}
              </Link>
            )}
          </li>
        ))}
      </ul>
    </nav>
  );
}

export function SiteFooter() {
  return (
    <footer className="mt-10 border-t border-[var(--edge-strong)] bg-[rgba(231,218,191,0.55)] sm:mt-16">
      <div aria-hidden className="h-[3px] w-full bg-[linear-gradient(90deg,#3b2715,#7a5330_22%,#a9853f_50%,#7a5330_78%,#3b2715)]" />
      <div className="mx-auto w-full max-w-[1180px] px-4 pb-[calc(1.5rem+env(safe-area-inset-bottom))] pt-5 sm:px-6 sm:pb-10 sm:pt-10">
        <div className="sm:hidden">
          <div className="flex items-center gap-2.5">
            <Logo size={46} />
            <div>
              <p className="font-display text-xl font-semibold text-ink">Paper<span className="text-wood-2">Raj</span></p>
              <p className="text-[0.68rem] text-ink-3">School question paper archive</p>
            </div>
          </div>
          <p className="mt-3 max-w-md font-serif-papr text-[0.86rem] leading-relaxed text-ink-2">
            {SITE.tagline}
          </p>
          <details className="mt-4 border-y border-[var(--edge)] py-2.5">
            <summary className="flex cursor-pointer list-none items-center justify-between font-semibold text-ink-2 [&::-webkit-details-marker]:hidden">
              <span>Explore PaperRaj</span><span aria-hidden className="text-lg text-gold">+</span>
            </summary>
            <div className="mt-3 grid grid-cols-2 gap-4">
              {LINK_GROUPS.map((group) => (
                <FooterLinks key={group.title} group={group} />
              ))}
            </div>
          </details>
          <div className="mt-4 flex items-center justify-between gap-3 text-[0.68rem] text-ink-3">
            <span>© {new Date().getFullYear()} {SITE.legalName}</span>
            <Link href="/admin" aria-label="Librarian desk" className="text-gold">✦</Link>
          </div>
        </div>

        <div className="hidden sm:grid sm:grid-cols-[1.4fr_repeat(3,minmax(0,1fr))] sm:gap-9">
          <div>
            <div className="flex items-center gap-3">
              <Logo size={48} />
              <span className="font-display text-2xl font-semibold text-ink">Paper<span className="text-wood-2">Raj</span></span>
            </div>
            <p className="mt-4 max-w-sm font-serif-papr text-[0.95rem] leading-relaxed text-ink-2">{SITE.description}</p>
            <p className="mt-3 font-serif-papr text-[0.95rem] italic text-ink-3">“{SITE.tagline}”</p>
            <a href={`mailto:${SITE.ownerEmail}`} className="link-ink mt-4 inline-block text-sm">{SITE.ownerEmail}</a>
          </div>
          {LINK_GROUPS.map((group) => <FooterLinks key={group.title} group={group} />)}
        </div>

        <div className="hidden sm:flex mt-9 items-center justify-between gap-3 border-t border-[var(--edge)] pt-5 text-[0.8rem] text-ink-3">
          <p>© {new Date().getFullYear()} {SITE.legalName} · PaperRaj. Built for students, teachers and archivists.</p>
          <p className="flex items-center gap-3"><span>Installable on Android &amp; iPhone</span><Link href="/admin" aria-label="Librarian desk" className="text-ink-3/70 hover:text-gold">✦</Link></p>
        </div>
      </div>
    </footer>
  );
}
''')

# Library action hierarchy: details/view side by side, download gets priority on mobile.
lib = root / "src/components/Library.tsx"
s = lib.read_text(encoding="utf-8")
s = s.replace('className="flex shrink-0 flex-wrap gap-2 sm:flex-col sm:items-stretch"', 'className="mobile-paper-actions grid grid-cols-2 gap-1.5 sm:flex sm:shrink-0 sm:flex-col sm:items-stretch sm:gap-2"')
s = s.replace('className="btn btn-sm flex-1 sm:flex-none"', 'className="btn btn-sm min-w-0"', 2)
s = s.replace('className="btn btn-primary btn-sm flex-1 sm:flex-none"', 'className="btn btn-primary btn-sm col-span-2 sm:col-span-1"')
lib.write_text(s, encoding="utf-8")
print("✓ src/components/Library.tsx: mobile action hierarchy")

# Viewer: smaller mobile chrome and less vertical waste.
viewer = root / "src/components/PaperViewer.tsx"
s = viewer.read_text(encoding="utf-8")
s = s.replace('className="grid gap-3"', 'className="grid gap-2.5 sm:gap-3"', 1)
s = s.replace('className="flex flex-wrap items-center justify-between gap-2"', 'className="flex items-center justify-between gap-2"', 1)
s = s.replace('className="smallcaps text-[0.74rem] font-bold text-ink-3"', 'className="min-w-0 truncate smallcaps text-[0.66rem] font-bold text-ink-3 sm:text-[0.74rem]"', 1)
s = s.replace('className="flex flex-wrap gap-2"', 'className="flex shrink-0 gap-1.5"', 1)
s = s.replace('className="btn btn-ghost btn-sm"\n          >\n            Download', 'className="btn btn-ghost btn-sm !min-h-[38px] !px-2.5 sm:!min-h-[40px]"\n          >\n            Download', 1)
s = s.replace('className="btn btn-ghost btn-sm"\n            onClick={() => setOpen(false)}', 'className="btn btn-ghost btn-sm !min-h-[38px] !px-2.5 sm:!min-h-[40px]"\n            onClick={() => setOpen(false)}', 1)
s = s.replace('className="flex min-h-[60vh] items-center justify-center bg-[#f8f5ec] p-2 sm:p-4"', 'className="flex min-h-[54vh] items-center justify-center bg-[#f8f5ec] p-1.5 sm:min-h-[60vh] sm:p-4"')
s = s.replace('className="max-h-[75vh] w-auto max-w-full select-none object-contain"', 'className="max-h-[68vh] w-auto max-w-full select-none object-contain sm:max-h-[75vh]"')
s = s.replace('className="flex items-center justify-center gap-3"', 'className="grid grid-cols-[1fr_auto_1fr] items-center gap-2"', 1)
s = s.replace('className="btn btn-ghost"\n              disabled={page <= 1}', 'className="btn btn-ghost w-full px-2 text-[0.8rem] sm:px-4 sm:text-sm"\n              disabled={page <= 1}', 1)
s = s.replace('className="min-w-[80px] text-center text-sm text-ink-3"', 'className="min-w-[54px] text-center text-xs font-semibold text-ink-3 sm:min-w-[80px] sm:text-sm"')
s = s.replace('className="btn btn-ghost"\n              disabled={page >= totalPages}', 'className="btn btn-ghost w-full px-2 text-[0.8rem] sm:px-4 sm:text-sm"\n              disabled={page >= totalPages}', 1)
viewer.write_text(s, encoding="utf-8")
print("✓ src/components/PaperViewer.tsx: compact reader chrome")

# Global mobile polish. Append a scoped layer so existing desktop styling remains intact.
globals = root / "src/app/globals.css"
s = globals.read_text(encoding="utf-8")
layer = r'''

/* ---------------------------------------------------------------- */
/* PaperRaj mobile product layer                                    */
/* ---------------------------------------------------------------- */
@media (max-width: 767px) {
  main#main {
    padding-left: 0.75rem;
    padding-right: 0.75rem;
    padding-top: 1rem;
    padding-bottom: 1rem;
  }

  .paper {
    border-radius: 8px;
    box-shadow: 0 1px 2px rgba(60, 42, 24, 0.06), 0 8px 22px -18px rgba(60, 42, 24, 0.35);
  }

  .btn {
    min-height: 42px;
    padding: 0.52rem 0.85rem;
    border-radius: 7px;
    font-size: 0.88rem;
  }

  .btn-sm {
    min-height: 40px;
    padding: 0.42rem 0.72rem;
    border-radius: 7px;
    font-size: 0.8rem;
  }

  .chip {
    padding: 0.16rem 0.45rem;
    font-size: 0.7rem;
  }

  .mobile-paper-actions .btn {
    width: 100%;
  }

  input.field,
  select.field,
  textarea.field {
    border-radius: 7px;
  }

  .row-hover:hover {
    transform: none;
    box-shadow: none;
  }
}

@media (max-width: 380px) {
  main#main {
    padding-left: 0.625rem;
    padding-right: 0.625rem;
  }

  .mobile-paper-actions {
    gap: 0.35rem;
  }
}
'''
if 'PaperRaj mobile product layer' not in s:
    globals.write_text(s + layer, encoding="utf-8")
    print("✓ src/app/globals.css: mobile product layer")
else:
    print("✓ src/app/globals.css: mobile product layer (already applied)")
PY

echo
 echo "Running checks..."
if git diff --check; then echo "✓ git diff --check"; else echo "ERROR: git diff --check failed"; exit 1; fi

if npm run typecheck; then echo "✓ typecheck passed"; else echo "ERROR: typecheck failed"; exit 1; fi

if npm run build; then echo "✓ build passed"; else echo "ERROR: build failed"; exit 1; fi

echo
cat <<EOF
==============================================
PAPERRAJ MOBILE REDESIGN APPLIED SUCCESSFULLY
==============================================
Backup: $BACKUP

Included:
✓ Supplied PaperRaj logo
✓ Compact mobile-first homepage
✓ Removed oversized "ancient library" hero
✓ Clear Browse / Upload hierarchy
✓ Compact stats
✓ Cleaner paper-card actions
✓ Compact document reader controls
✓ Compact expandable mobile footer
✓ Mobile spacing, typography and touch-target refinement
✓ Desktop layout preserved as much as possible

No commit or push was performed.
EOF
